:root {
  --font-sans:
    "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", monospace;

  --font-text: "Zen Kaku Gothic Antique", sans-serif;
  --font-headers: "PT Sans", sans-serif;

  --font-size-xs: 0.75rem; /* 12px */
  --font-size-sm: 0.875rem; /* 14px */
  --font-size-base: 1rem; /* 16px */
  --font-size-lg: 1.125rem; /* 18px */
  --font-size-xl: 1.25rem; /* 20px */
  --font-size-xxl: 1.5rem; /* 24px */
  --font-size-3xl: 2rem; /* 32px */

  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  --line-height-none: 1;
  --line-height-tight: 1.25;
  --line-height-normal: 1.5;
  --line-height-loose: 2;
}

:root {
  /*== Color Assignments ==*/
  --color-primary: #2476ff;
  --color-primary-light: #5e9aff;
  --color-primary-dark: #0965ff;

  --color-secondary: #747474;
  --color-secondary-light: #333;
  --color-secondary-dark: #292929;

  --color-tertiary: #f97316;
  --color-tertiary-light: #ffa261;
  --color-tertiary-dark: #c95300;

  --color-almost-black: #333;
  --color-almost-white: #fcfcfc;

  --color-success: #009112;
  --color-success-light: #98FF98;
  --color-warning: #ff9017;
  --color-warning-light: #FFEAD5;
  --color-error: #fa3434;
  --color-error-light: #FDD0D0;

  /*== Text Colors ==*/
  --color-text-base: #333;
  --color-text-alt: #fff;

  /*== Background Colors ==*/
  --color-bg: #eee;
  --color-bg-alt: #222;

  --bg-primary: linear-gradient(0deg, #0965ff 0%, #2476ff 100%);
  --bg-secondary: linear-gradient(0deg, #292929 0%, #747474 100%);
  --bg-tertiary: linear-gradient(0deg, #bbb 0%, #fff 100%);

  --color-border: var(--gray-200);
  --color-border-hover: var(--gray-300);


  /*== Gradients ==*/
  --bg-gradient-1: linear-gradient(0deg, #2476ff 0%, #5e9aff 100%);
  --bg-gradient-2: linear-gradient(0deg, #fff 0%, #5e9aff 100%);
  --bg-gradient-3: linear-gradient(0deg, #0965ff 0%, #2476ff 100%);
  --bg-gradient-4: linear-gradient(
    180deg,
    rgba(94, 154, 255, 1) 0%,
    rgba(36, 118, 255, 1) 50%,
    rgba(0, 90, 238, 1) 100%
  );
  --background-gradient-5: radial-gradient(
    circle,
    rgba(94, 154, 255, 1) 0%,
    rgba(36, 118, 255, 1) 100%
  );
  --bg-gradient-6: radial-gradient(
    circle,
    rgba(238, 238, 238, 1) 0%,
    rgba(193, 216, 255, 1) 100%
  );
  --bg-gradient-7: repeating-linear-gradient(
    45deg,
    #2476ff,
    #5e9aff 20px,
    #fff 20px,
    #ccc 32px
  );
  --background-gradient-8: repeating-linear-gradient(
    45deg,
    #5e9aff,
    #0965ff 20px,
    #000 20px,
    #444 32px
  );

  /*== Borders ==*/
  --border: 2px solid #2476ff;
  --border-light: 2px solid #5e9aff;
  --border-dark: 2px solid #0965ff;

  --border-sm: 1px solid #2476ff;
  --border-sm-light: 1px solid #5e9aff;
  --border-sm-dark: 1px solid #0965ff;

  --border-lg: 4px solid #2476ff;
  --border-lg-light: 4px solid #5e9aff;
  --border-lg-dark: 4px solid #0965ff;

  /*== Shadows (Composable) ==*/
  --shadow-sm: 0 1px 2px 0 hsla(0, 0%, 0%, 0.05);
  --shadow-md:
    0 4px 6px -1px hsla(0, 0%, 0%, 0.1), 0 2px 4px -2px hsla(0, 0%, 0%, 0.1);
  --shadow-lg:
    0 10px 15px -3px hsla(0, 0%, 0%, 0.1), 0 4px 6px -4px hsla(0, 0%, 0%, 0.1);
  --shadow-inner: inset 0 2px 4px 0 hsla(0, 0%, 0%, 0.05);
}

:root {

  /*== Sizes ==*/
  --space-px: 1px;
  --space-1: 0.25rem; /* 4px */
  --space-2: 0.5rem; /* 8px */
  --space-3: 0.75rem; /* 12px */
  --space-4: 1rem; /* 16px */
  --space-5: 1.25rem; /* 20px */
  --space-6: 1.5rem; /* 24px */
  --space-8: 2rem; /* 32px */
  --space-10: 2.5rem; /* 40px */
  --space-12: 3rem; /* 48px */
  --space-16: 4rem; /* 64px */

  --space-x: var(--space-12); /* Horizontal default spacing */
  --space-y: var(--space-8); /* Vertical default spacing */

  /*== Borders & Radii ==*/
  --border-width-sm: 1px;
  --border-width-md: 2px;

  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;
  --radius-full: 9999px;

  /*== Breakpoints (Single Source of Truth) ==*/
  /* Note: CSS Custom Properties cannot be used directly in media query definitions. */
  /* These are for documentation and potential use in JS or preprocessors. */
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1440px;
}

