::placeholder {
    /* Chrome, Firefox, Opera, Safari 10.1+ */
    color: var(--text_color);
    opacity: 0.5;
}

.night ::placeholder {
    /* Chrome, Firefox, Opera, Safari 10.1+ */
    color: var(--text_color_alt);
    opacity: 0.5;
}

.input-container {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
    margin: 10px 5px;
}

.input-container span {
    max-width: 120px;
    margin: 10px 10px 10px 0;
    overflow-wrap: break-word;
    word-wrap: break-word;
    white-space: normal;
}

.inputLine input {
    border-radius: 0;
    border-width: 0 0 2px 0;
    text-align: left;
    padding: 0 10px 0 30px;
    min-width: 120px;
}

select {
    appearance: none;
    outline: 0;
    box-shadow: none;
    min-width: 220px;
    height: 100%;
    margin: 0;
    padding: 6px 12px;
    color: var(--text_color);
    font-weight: 700;
    cursor: pointer;
    background: none;
    color: var(--text_color);
    border: var(--border);
    border-radius: var(--radius);
    cursor: pointer;
    line-height: 1;
    min-width: 100px;
    margin-right: 15px;
}

.select {
    position: relative;
    overflow: hidden;
    background: rgba(var(--primary_color_rgb), 0.2);
    border-radius: var(--radius);
    margin: 10px 20px;
    box-shadow: 0 0 15px 2px rgba(255, 255, 255, 0.12);
}

.select::after {
    content: '\25BC';
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    padding: 3px 5px;
    background: none;
    color: var(--text_color_alt);
    pointer-events: none;
    background: var(--primary_color);
}

.select::after {
    -webkit-transition: .5s all ease;
    -o-transition: .5s all ease;
    transition: .5s all ease;
}

.checkboxContainer {
    position: relative;
    display: block;
    cursor: pointer;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    margin: 8px 30px 10px 10px;
    padding: 5px 25px;
}

input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    height: 0;
    width: 0;
}

.checkmark {
    position: absolute;
    top: 0;
    height: 25px;
    width: 25px;
    margin-left: 25px;
    border-radius: 8px;
    border: 3px solid var(--primary_color);
    cursor: pointer;
}

.checkbox input:checked ~ .checkmark {
    background-color: var(--primary_color);
    box-shadow: 0 0 8px 1px var(--primary_color);
    border-radius: 6px;
}

.checkbox .checkmark:after {
    left: 8px;
    top: -10px;
    width: 10px;
    height: 28px;
    border: solid white;
    border-width: 0 5px 5px 0;
    -webkit-transform: rotate(45deg);
    -ms-transform: rotate(45deg);
    transform: rotate(45deg);
}

.toggle + .toggle-btn {
    outline: 0;
    display: block;
    width: 32px;
    height: 18px;
    position: relative;
    cursor: pointer;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
}

.toggle + .toggle-btn:after,
.toggle + .toggle-btn:before {
    position: relative;
    display: block;
    content: "";
    width: 50%;
    height: 100%;
}

.toggle + .toggle-btn:after,
.toggle + .toggle-btn:before {
    position: relative;
    display: block;
    content: "";
    width: 50%;
    height: 100%;
}

.toggle + .toggle-btn {
    background: #ccc;
    border-radius: 2em;
    padding: 2px;
    transition: all .4s ease;
}

.radio-group {
    border-color: var(--primary_color);
    border-style: solid;
    width: fit-content;
    border-width: 2px;
    left: 0;
    right: 0;
    margin: auto;
    margin-top: 10px;
    margin-bottom: 10px;
    border-radius: 30px;
    padding: 3px 0px;
}

.radio-group input {
    position: absolute !important;
    clip-path: rect(0, 0, 0, 0);
    height: 0px;
    width: 0px;
    border: 0;
    overflow: hidden;
}

.radio-group label {
    text-align: center;
    padding: 5px 12px;
    background: none;
    color: var(--primary_color);
}

.radio-group input:checked + label {
    background-color: var(--primary_color);
    background: var(--primary_background);
    color: var(--text_color_alt);
    box-shadow: 0 0px 5px 0px var(--primary_color);
    border-radius: 15px;
    padding: 8px 15px;
}

.radio-btns input {
    position: absolute !important;
    clip-path: rect(0, 0, 0, 0);
    height: 1px;
    width: 1px;
    border: 0;
    overflow: hidden;
}

.radio-btns label {
    cursor: pointer;
    text-align: center;
    padding: 5px 12px;
    background: none;
    color: var(--primary_color);
    border-color: var(--primary_color);
    border-style: solid;
    border-width: 2px;
    border-radius: 15px;
    margin: 0 5px;
}

.radio-btns input:checked + label {
    background: var(--primary_background);
    border: none;
    padding: 7px 15px;
    color: var(--text_color_alt);
    box-shadow: 0 0px 5px 0px var(--primary_color);
}

.radio-divs input {
    position: absolute !important;
    clip-path: rect(0, 0, 0, 0);
    height: 1px;
    width: 1px;
    border: 0;
    overflow: hidden;
}

.radio-divs label {
    cursor: pointer;
    text-align: center;
    background: none;
    color: var(--primary_color);
    margin: 0 15px;
    display: inline-block;
}

.radio-divs input:checked + label div {
    box-shadow: 0 0px 15px 0px var(--primary_color);
    transform: scale(1.3);
}

.file-btn {
    box-shadow: none;
    border-radius: 8px;
    border: 2px solid 75px;
    background: var(--primary_color);
    cursor: pointer;
    font-family: var(--font_headers);
    font-weight: 900;
    letter-spacing: 1px;
    margin: 1vh 1vw;
    color: #fff;
    padding: 10px 1.2vw 7px 1.2vw;
    min-width: var(--size_xl);
    width: min-content;
}

.range-container {
    display: flex;
    justify-content: center;
    align-items: center;
}

.before-absolute::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.after-absolute::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.before-overlay::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.after-overlay::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

